use num_traits::ToPrimitive;
use serde_json::json;
use zopro_gaussian_fr_probe::model::Params;
fn main(){let p=Params::new();let mut s=String::from("// Derived from the exact BN254 Fr identity; see model.rs.\n");for(n,v)in[("A",&p.a),("B",&p.b),("HALF",&p.half),("BOUND",&p.bound),("KRE",&p.neg_inv.re),("KIM",&p.neg_inv.im)]{s+=&format!("pub const {n}:u128={}u128;\n",v.to_u128().unwrap());}std::fs::write("/tmp/zopro-gaussian-fr/src/constants.rs",s).unwrap();let max=(2u32*&p.bound*&p.bound+&p.radix-1u32)/&p.radix+(&p.a+&p.b+1u32)/2u32;let import=(&p.prime+&p.radix-1u32)/&p.radix+(&p.a+&p.b+1u32)/2u32;assert!(&import+&p.b<p.a);std::fs::write("/tmp/zopro-gaussian-fr/model-gate.json",serde_json::to_vec_pretty(&json!({"passed":true,"prime":p.prime.to_string(),"a":p.a.to_string(),"b":p.b.to_string(),"radix":p.radix.to_string(),"bound":p.bound.to_string(),"product_pre_correction_bound":max.to_string(),"import_pre_correction_bound":import.to_string(),"both_bounds_plus_b_below_a":true,"coordinates_fit_i128":true,"stored_bytes":32,"native_vectors":6,"baseline_native_vectors":5,"production_changed":false,"SDK_requests":0,"Gnark_exports":0})).unwrap()).unwrap();println!("Gaussian Fr constants and exact product/import bounds verified");}
